Prob030_popcount255.code:
module TopModule (
    input  [254:0] in,
    output [7:0]   out
);

    // Internal signals for the carry-save adder tree
    // We need enough bits to hold the maximum count (255) -> 8 bits
    // Internal width is 9 bits to handle the final reduction.
    reg [8:0] count;

    integer i;

    always @(*) begin
        // Initialize the accumulator
        count = 9'b0;

        // Process 9 bits at a time.
        // Since 255 = 9 * 28 + 3, we process 28 groups of 9 bits,
        // followed by the remaining 3 bits.

        // Process groups of 9
        for (i = 0; i < 28; i = i + 1) begin
            // Sum the 9 bits: in[9*i +: 9]
            // The reduction: popcount of 9 bits fits in 5 bits, 
            // but we use 9 bits internally for simplicity and chaining.
            count = count + in[9*i +: 9];
        end

        // Handle the remaining 3 bits (indices 252, 253, 254)
        // These are added to the accumulated count.
        count = count + in[252] + in[253] + in[254];
    end

    // The result is the lower 8 bits of the internal count.
    // The 9th bit (index 8) is discarded as the max count is 255 (8 bits).
    assign out = count[7:0];

endmodule

