module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output q
);

    // Combinational logic: q = (a & b & c & d) | (a & ~b & c) | (~a & b & c & d) | (~a & ~b & c)
    // This simplifies to: q = c & (a & b & d | a & ~b | ~a & b & d | ~a & ~b)
    // Further simplification yields: q = c & (a & (b & d | ~b) | ~a & (b & d | ~b))
    // Which reduces to: q = c & (a | ~a) & (b & d | ~b) ... actually let's just use the truth table directly.

    assign q = (a & b & c & d) |
               (a & ~b & c) |
               (~a & b & c & d) |
               (~a & ~b & c);

endmodule

