module TopModule (
    input  clk,
    input  areset,
    input  x,
    output z
);

    // One-hot encoded state register
    // State A: 2'b01 (bit 0 set)
    // State B: 2'b10 (bit 1 set)
    reg [1:0] state;
    reg [1:0] next_state;

    // Output assignment (Mealy output depends on current state and input x)
    assign z = (state == 2'b10) ? ~x : x; // z = 1 when in B and x=0; z = 1 when in A and x=1; z = 0 when in A and x=0

    // Next-state logic (combinational)
    always @(*) begin
        case (state)
            2'b01: // State A
                if (x)
                    next_state = 2'b10; // B
                else
                    next_state = 2'b01; // A
            2'b10: // State B
                if (x)
                    next_state = 2'b10; // B (stay)
                else
                    next_state = 2'b10; // B (stay)
            default: next_state = 2'b01; // Fallback to A
        endcase
    end

    // State register (positive edge-triggered, asynchronous active-high reset)
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 2'b01; // Reset to state A
        else
            state <= next_state;
    end

endmodule

