module TopModule (
    input  c,
    input  d,
    output [3:0] mux_in
);

    // Assign the four K-map outputs to the mux_in vector.
// The K-map truth table (rows: cd, cols: ab = 00,01,11,10):
//        00  01  11  10
//  00:   0   0   0   1
//  01:   1   0   0   0
//  11:   1   0   1   1
//  10:   1   0   0   1
//
// mux_in[0] corresponds to ab=00  ->  mux_in[0] = c' d' + c d' + c d + c d'
// mux_in[1] corresponds to ab=01  ->  mux_in[1] = c' d' + c' d'
// mux_in[2] corresponds to ab=11  ->  mux_in[2] = c' d' + c' d + c d
// mux_in[3] corresponds to ab=10  ->  mux_in[3] = c' d' + c d' + c d

    assign mux_in[0] = ~c & ~d | c & ~d | c & d | ~c & d;
    assign mux_in[1] = ~c & ~d | ~c & d;
    assign mux_in[2] = ~c & ~d | ~c & d | c & d;
    assign mux_in[3] = ~c & ~d | c & ~d | c & d;

endmodule

