    typedef enum logic [2:0] {
        IDLE      = 3'b000,
        START     = 3'b001,
        DATA      = 3'b010,
        STOP      = 3'b011,
        WAIT_STOP = 3'b100
    } state_t;

    // Signals
    state_t state, next_state;
    logic [7:0] data_reg, next_data;
    logic [3:0] bit_cnt, next_bit_cnt;
    logic       done_reg, next_done;

    // Output assignments
    assign out_byte = data_reg;
    assign done     = done_reg;

    // State register (synchronous reset, positive edge)
    always_ff @(posedge clk) begin
        if (reset) begin
            state      <= IDLE;
            data_reg   <= 8'b0;
            bit_cnt    <= 4'd0;
            done_reg   <= 1'b0;
        end else begin
            state      <= next_state;
            data_reg   <= next_data;
            bit_cnt    <= next_bit_cnt;
            done_reg   <= next_done;
        end
    end

    // Next-state logic
    always_comb begin
        // Default assignments (keep current values if no transition)
        next_state      = state;
        next_data       = data_reg;
        next_bit_cnt    = bit_cnt;
        next_done       = done_reg;

        case (state)
            IDLE: begin
                if (in == 1'b0) begin // Start bit detected (falling edge)
                    next_state = START;
                    next_bit_cnt = 4'd0; // Reset bit counter for data bits
                end else begin
                    next_state = IDLE;
                end
            end

            START: begin
                // Wait one clock cycle to sample the start bit (optional but good practice)
                // Then transition to DATA state to capture the first data bit (LSB)
                next_state = DATA;
            end

            DATA: begin
                // Shift in the incoming bit (LSB first)
                next_data = {in, data_reg[7:1]};
                next_bit_cnt = bit_cnt + 1'b1;

                // If we have received 8 data bits, go to STOP state
                if (bit_cnt == 4'd7) begin
                    next_state = STOP;
                end else begin
                    next_state = DATA;
                end
            end

            STOP: begin
                // Verify the stop bit is high (1)
                if (in == 1'b1) begin
                    // Stop bit correct: assert done and load data as valid
                    next_done = 1'b1;
                    next_state = IDLE; // Ready for next byte
                end else begin
                    // Stop bit incorrect: stay in STOP state waiting for a high level
                    next_state = STOP;
                    next_done  = 1'b0;
                end
            end

            default: next_state = IDLE;
        endcase
    end

