module TopModule (
    input  clk,
    input  reset,
    input  in,
    output done
);

    // State encoding: 4 bits are used to provide unique values for all states
    typedef enum logic [3:0] {
        IDLE      = 4'b0000,
        START     = 4'b0001,
        DATA0     = 4'b0010,
        DATA1     = 4'b0011,
        DATA2     = 4'b0100,
        DATA3     = 4'b0101,
        DATA4     = 4'b0110,
        DATA5     = 4'b0111,
        DATA6     = 4'b1000,
        DATA7     = 4'b1001,
        STOP      = 4'b1010,
        ERROR     = 4'b1011
    } state_t;

    state_t state, next_state;

    // Counter for data bits (3 bits: 0-7)
    logic [2:0] bit_cnt;
    logic [2:0] next_bit_cnt;

    // Shift register for the 8 data bits (LSB first)
    logic [7:0] shift_reg;
    logic [7:0] next_shift_reg;

    // Output register for 'done'
    logic done_reg;
    logic next_done;

    // -------------------------------------------------
    // Next-state and output logic (combinational)
    // -------------------------------------------------
    always_comb begin
        next_state   = state;
        next_bit_cnt = bit_cnt;
        next_shift_reg = shift_reg;
        next_done    = done_reg;

        case (state)
            IDLE: begin
                if (~in) begin
                    // Start bit detected (falling edge)
                    next_state = START;
                    next_bit_cnt = 3'd0;
                end else begin
                    next_state = IDLE;
                end
            end

            START: begin
                // Wait for one clock cycle to sample the start bit
                // Then move to data bit 0
                next_state = DATA0;
            end

            DATA0, DATA1, DATA2, DATA3, DATA4, DATA5, DATA6, DATA7: begin
                // Shift in the data bit (LSB first)
                next_shift_reg = {in, shift_reg[7:1]};
                next_bit_cnt   = bit_cnt + 1'b1;

                // If we have received 8 bits, go to STOP state
                if (bit_cnt == 3'd7) begin
                    next_state = STOP;
                end else begin
                    // Move to next data state
                    case (bit_cnt)
                        3'd0: next_state = DATA1;
                        3'd1: next_state = DATA2;
                        3'd2: next_state = DATA3;
                        3'd3: next_state = DATA4;
                        3'd4: next_state = DATA5;
                        3'd5: next_state = DATA6;
                        3'd6: next_state = DATA7;
                        default: next_state = DATA0;
                    endcase
                end
            end

            STOP: begin
                // Verify the stop bit is high (1)
                if (in) begin
                    // Stop bit correct -> assert done and go to IDLE
                    next_done    = 1'b1;
                    next_state   = IDLE;
                end else begin
                    // Stop bit incorrect -> wait, stay in STOP
                    next_state = STOP;
                    next_done  = 1'b0;
                end
            end

            ERROR: begin
                // Should not normally be reached, but if we find a start bit
                // while in an unexpected state, restart.
                if (~in) begin
                    next_state = START;
                end else begin
                    next_state = ERROR;
                end
            end

            default: next_state = IDLE;
        endcase
    end

    // -------------------------------------------------
    // Sequential logic (flip-flops)
    // -------------------------------------------------
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state       <= IDLE;
            bit_cnt     <= 3'd0;
            shift_reg   <= 8'd0;
            done_reg    <= 1'b0;
        end else begin
            state       <= next_state;
            bit_cnt     <= next_bit_cnt;
            shift_reg   <= next_shift_reg;
            done_reg    <= next_done;
        end
    end

    // Assign the output port
    assign done = done_reg;

endmodule

