module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output walk_left,
    output walk_right,
    output aaah
);

    // State encoding: 2 bits
    // 2'b00: WALK_LEFT
    // 2'b01: WALK_RIGHT
    // 2'b10: FALLING
    // 2'b11: RESERVED (unused)
    typedef enum logic [1:0] {
        WALK_LEFT  = 2'b00,
        WALK_RIGHT = 2'b01,
        FALLING    = 2'b10
    } state_t;

    state_t state, next_state;
    logic dir_mem; // 1'b0 = LEFT, 1'b1 = RIGHT

    // Next-state logic (combinational)
    always_comb begin
        next_state = state; // default: stay in current state

        if (state == FALLING) begin
            if (ground == 1) begin
                // Ground reappears: resume walking in same direction as before the fall
                if (dir_mem == 1'b0)
                    next_state = WALK_LEFT;
                else
                    next_state = WALK_RIGHT;
            end else begin
                // Ground still 0: stay falling
                next_state = FALLING;
            end
        end else begin // state is WALK_LEFT or WALK_RIGHT
            if (ground == 0) begin
                // Fall detection
                next_state = FALLING;
            end else begin
                // Ground is high, check bumps
                if (bump_left && bump_right) begin
                    // Bumped both sides: switch direction
                    if (state == WALK_LEFT)
                        next_state = WALK_RIGHT;
                    else
                        next_state = WALK_LEFT;
                end else if (bump_left) begin
                    // Bumped left: walk right
                    next_state = WALK_RIGHT;
                end else if (bump_right) begin
                    // Bumped right: walk left
                    next_state = WALK_LEFT;
                end else begin
                    // No bump, stay in current walking state
                    next_state = state;
                end
            end
        end
    end

    // Sequential logic (positive edge triggered, asynchronous active-high reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
            dir_mem <= 1'b0; // Initialize to LEFT
        end else begin
            state <= next_state;

            // Update dir_mem based on current state (before clock edge) and next_state
            // Rules for dir_mem:
            // - If current state is WALK_LEFT -> dir_mem = 0
            // - If current state is WALK_RIGHT -> dir_mem = 1
            // - If current state is FALLING -> dir_mem holds previous value (no change)
            if (state == WALK_LEFT)
                dir_mem <= 1'b0;
            else if (state == WALK_RIGHT)
                dir_mem <= 1'b1;
            else if (state == FALLING)
                dir_mem <= dir_mem; // hold previous value
            else
                dir_mem <= 1'b0;
        end
    end

    // Output logic (Moore machine: outputs depend only on state)
    assign walk_left = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);
    assign aaah = (state == FALLING);

endmodule

