module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [511:0] data,
    output logic [511:0] q
);

    // Internal register to hold the current state
    logic [511:0] q_reg;

    // Combinational logic for the next state of each cell
    // We generate 512 instances, one per cell.
    // Boundary conditions: left of cell 0 is 0, right of cell 511 is 0.
    genvar i;
    always_comb begin
        for (i = 0; i < 512; i = i + 1) begin
            // Determine Left, Center, Right neighbors
            logic left, center, right;

            // Left neighbor: cell i-1, or 0 if i == 0
            if (i == 0)
                left = 1'b0;
            else
                left = q_reg[i-1];

            // Center neighbor: current cell
            center = q_reg[i];

            // Right neighbor: cell i+1, or 0 if i == 511
            if (i == 511)
                right = 1'b0;
            else
                right = q_reg[i+1];

            // Apply Rule 110 truth table
            // The table maps (Left, Center, Right) -> Next State
            // 111 -> 0
            // 110 -> 1
            // 101 -> 1
            // 100 -> 0
            // 011 -> 1
            // 010 -> 1
            // 001 -> 1
            // 000 -> 0
            // This is equivalent to: (Left & ~Center & ~Right) |
            //                       (~Left & Center & Right) |
            //                       (~Left & Center & ~Right)
            // But we implement it directly from the truth table for clarity.
            if ((left == 1'b1) && (center == 1'b1) && (right == 1'b1))
                q[i] = 1'b0;
            else if ((left == 1'b1) && (center == 1'b1) && (right == 1'b0))
                q[i] = 1'b1;
            else if ((left == 1'b1) && (center == 1'b0) && (right == 1'b1))
                q[i] = 1'b1;
            else if ((left == 1'b1) && (center == 1'b0) && (right == 1'b0))
                q[i] = 1'b0;
            else if ((left == 1'b0) && (center == 1'b1) && (right == 1'b1))
                q[i] = 1'b1;
            else if ((left == 1'b0) && (center == 1'b1) && (right == 1'b0))
                q[i] = 1'b1;
            else if ((left == 1'b0) && (center == 1'b0) && (right == 1'b1))
                q[i] = 1'b1;
            else // (left == 0) && (center == 0) && (right == 0)
                q[i] = 1'b0;
        end
    end

    // Sequential logic: update on positive edge of clk
    always_ff @(posedge clk) begin
        if (load)
            q_reg <= data;
        else
            q_reg <= q;
    end

    // Assign the registered output
    assign q = q_reg;

endmodule

