module TopModule (
    input  clk,
    input  reset,
    input  data,
    input  done_counting,
    input  ack,
    output shift_ena,
    output counting,
    output done
);

// State encoding
// We use 3 bits to support 7 states (0-6).
// Encoding: 
// 000: IDLE
// 001: SHIFT1
// 010: SHIFT2
// 011: SHIFT3
// 100: SHIFT4
// 101: COUNTING
// 110: DONE_STATE
typedef enum logic [2:0] {
    IDLE       = 3'b000,  // Searching for 1101 pattern
    SHIFT1     = 3'b001,  // Shift cycle 1
    SHIFT2     = 3'b010,  // Shift cycle 2
    SHIFT3     = 3'b011,  // Shift cycle 3
    SHIFT4     = 3'b100,  // Shift cycle 4
    COUNTING   = 3'b101,  // Waiting for done_counting
    DONE_STATE = 3'b110   // Asserted done, waiting for ack
} state_t;

state_t state, next_state;

// Shift register to detect the pattern 1101
// We keep the last 4 bits of the serial stream
logic [3:0] shift_reg;

// Next-state and output logic (Moore machine)
always_ff @(posedge clk) begin
    if (reset) begin
        shift_reg <= 4'b0000;
        state     <= IDLE;
    end else begin
        // Shift in the new data bit
        shift_reg <= {shift_reg[2:0], data};

        // Update state based on next_state logic
        state <= next_state;
    end
end

// Next-state and output logic
always_comb begin
    // Default assignments: keep outputs unchanged unless transitioning
    shift_ena  = 1'b0;
    counting   = 1'b0;
    done       = 1'b0;
    next_state = state; // Default: stay in current state

    case (state)
        IDLE: begin
            // Look for the pattern 1101 on the newly shifted value.
            // If the new shift_reg equals 1101, transition to SHIFT1.
            if (shift_reg == 4'b1101) begin
                next_state = SHIFT1;
            end else begin
                next_state = IDLE;
            end
        end

        SHIFT1: begin
            // Assert shift_ena for exactly 4 clock cycles
            shift_ena = 1'b1;
            // Transition to next shift cycle
            next_state = SHIFT2;
        end

        SHIFT2: begin
            shift_ena = 1'b1;
            next_state = SHIFT3;
        end

        SHIFT3: begin
            shift_ena = 1'b1;
            next_state = SHIFT4;
        end

        SHIFT4: begin
            shift_ena = 1'b1;
            // After 4 cycles, move to COUNTING
            next_state = COUNTING;
        end

        COUNTING: begin
            counting = 1'b1;
            if (done_counting) begin
                next_state = DONE_STATE;
            end else begin
                next_state = COUNTING;
            end
        end

        DONE_STATE: begin
            done = 1'b1;
            if (ack) begin
                next_state = IDLE;
            end else begin
                next_state = DONE_STATE;
            end
        end

        default: next_state = IDLE;
    endcase
end

endmodule

