module TopModule (
    input  clk,
    input  areset,

    input  predict_valid,
    input  [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,

    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);

    // 7-bit global branch history register
    reg [6:0] ghr;

    // 128-entry PHT (2-bit saturating counters)
    // Index: pc[6:0] XOR ghr[6:0] -> 7 bits -> 0 to 127
    reg [1:0] pht [0:127];

    // Internal wire for prediction index
    wire [6:0] predict_idx;

    // Internal wire for PHT counter read
    wire [1:0] counter;

    // Assign index for prediction: pc XOR ghr
    assign predict_idx = predict_pc ^ ghr;

    // Read PHT entry
    assign counter = pht[predict_idx];

    // Two-bit saturating counter MSB is taken prediction
    // Counter values: 00 (strong not taken), 01 (weak not taken), 10 (weak taken), 11 (strong taken)
    assign predict_taken = counter[1];

    // Predicted history: shift in the predicted taken/ntaken bit into LSB
    // and shift out the MSB
    assign predict_history = {counter[0], ghr[6:1]};

    // Training and Prediction logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'b0;
            // PHT is not explicitly reset here, retaining previous values unless initialized.
        end else begin
            // Default case: if neither train_valid nor predict_valid, GHR stays unchanged.
            // Priority: train_valid takes precedence over predict_valid for GHR update.

            if (train_valid) begin
                // Compute training index
                wire [6:0] train_idx = train_pc ^ train_history;

                // Update PHT entry
                // Training rule: 
                // If taken == 1: increment counter (if not already 11)
                // If taken == 0: decrement counter (if not already 00)
                if (train_taken) begin
                    if (pht[train_idx] < 2'b11)
                        pht[train_idx] <= pht[train_idx] + 1;
                end else begin
                    if (pht[train_idx] > 2'b00)
                        pht[train_idx] <= pht[train_idx] - 1;
