                // If mispredicted, recover GHR to the state after the mispredicting branch completes execution.
                // The specification implies updating the GHR with the actual outcome of the trained branch.
                // Standard GHR update: shift left, insert LSB = actual outcome (train_taken).
                ghr <= {train_history[5:0], train_taken};
            end else if (predict_valid) begin
                // Update GHR with the predicted outcome for the predicted branch.
                // This happens only if training is not active in this cycle.
                ghr <= {ghr[5:0], predict_taken};
            end
            // If both train_valid and predict_valid are 1, the 'if (train_valid)' branch executes,
            // satisfying the requirement that "training takes precedence".
        end
    end

    // Assign outputs
