module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic s,
    input  logic w,
    output logic z
);

    // State encoding: 2 bits are sufficient (A=00, B=01)
    typedef enum logic [1:0] {
        A = 2'b00,
        B = 2'b01
    } state_t;

    state_t state, next_state;

    // State register (synchronous reset, active high)
    always_ff @(posedge clk) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

    // Next-state logic
    always_comb begin
        // Default: stay in current state
        next_state = state;

        case (state)
            A: begin
                // Stay in A as long as s = 0; move to B when s = 1
                if (s == 1'b1)
                    next_state = B;
                // else remain in A
            end

            B: begin
                // From B, the FSM examines w for the next three clock cycles.
                // If w = 1 in exactly two of these clock cycles, then the FSM
                // has to set an output z to 1 in the following clock cycle.
                // Otherwise z has to be 0. The FSM continues checking w for
                // the next three clock cycles, and so on.
                //
                // To satisfy "continues checking w for the next three clock
                // cycles, and so on" while using as few states as possible,
                // we treat every clock cycle in state B as part of a sliding
                // window of the last three cycles.  z is asserted high in the
                // cycle immediately after exactly two w's have been seen in
                // the current window of three (including the current cycle).
                //
                // Count how many of the last three w values (including now)
                // are 1.  We keep the previous two w values in flip-flops.
                logic [1:0] cnt;
                // Initialise counter to 0 for this combinational block invocation
                cnt = 2'b00;

                // Count the three most recent w values:
                //   w (current) + w_hist[0] (previous) + w_hist[1] (two cycles ago)
                if (w == 1'b1) cnt = cnt + 1'b1;
                if (w_hist[0] == 1'b1) cnt = cnt + 1'b1;
                if (w_hist[1] == 1'b1) cnt = cnt + 1'b1;

                // Assert z in the cycle after exactly two 1's have been seen.
                // The specification requires z to be 1 in the *following* clock
                // cycle after the condition is met.  Here we simply drive z
                // based on the current count; the sequential block will update
                // z on the next clock edge.
                if (cnt == 2'b10)
                    z = 1'b1;
                else
                    z = 1'b0;
            end
        endcase
    end

    // Flip‑flops to hold the last two w values.
    // These are updated on every positive clock edge (when not reset).
    logic [1:0] w_hist;   // holds w_{n-1} and w_{n-2}

    always_ff @(posedge clk) begin
        if (reset) begin
            w_hist <= 2'b00;
            z      <= 1'b0;
        end else begin
            // Shift in the new w value: new w becomes w_hist[0],
            // old w_hist[0] becomes w_hist[1].
            w_hist <= { w_hist[0], w };

            // Output z is updated on the clock edge based on the count
            // computed in the combinational block.  The combinational
            // block drives z based on the current cnt; here we simply
            // register the output for the next cycle.
            // (The always_comb block above already assigns z, but the
            // flip‑flop below ensures the registered output follows the
            // sequential flow.  To avoid latch inference, we explicitly
            // assign z here as well.)
            z <= (w_hist[0] + w_hist[1] + w == 3'b111) ? 
                 (w_hist[0] + w_hist[1] + w == 3'b110 || 
                  w_hist[0] + w_hist[1] + w == 3'b101 || 
                  w_hist[0] + w_hist[1] + w == 3'b011) ? 
                 1'b1 : 1'b0 : 1'b0;
        end
    end

endmodule

Prob152_lemmings3.code:
module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding: 2 bits
    // 2'b00: WALKING_LEFT
    // 2'b01: WALKING_RIGHT
    // 2'b10: FALLING
    // 2'b11: DIGGING
    typedef enum logic [1:0] {
        WALKING_LEFT  = 2'b00,
        WALKING_RIGHT = 2'b01,
        FALLING       = 2'b10,
        DIGGING       = 2'b11
    } state_t;

    state_t state, next_state;

    // Direction register to remember walking direction across falls/digs
    // 0 = left, 1 = right
    reg [1:0] dir_reg;

    // State register (positive edge triggered, async active high reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALKING_LEFT;
            dir_reg <= 2'b00; // default direction left after reset
        end else begin
            state <= next_state;
            // Update direction register only when walking (not falling or digging)
            if (state == WALKING_LEFT || state == WALKING_RIGHT) begin
                dir_reg <= state;
            end
            // If falling and ground reappears, dir_reg retains the last walking direction
        end
    end

    // Next-state logic (combinational)
    always_comb begin
        // Default: stay in current state
        next_state = state;

        case (state)
            WALKING_LEFT: begin
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Fall takes precedence
                    next_state = FALLING;
                    // dir_reg keeps its value (remembers left direction)
                end else if (dig) begin
                    // Can dig only if on ground and dig signal active
                    // (bump check removed per spec: being bumped while digging has no effect,
                    // and fall has higher precedence than dig, so if !ground falls first,
                    // here ground=1 so we check dig)
                    next_state = DIGGING;
                end else begin
                    // Switch direction if bumped (including both sides)
                    if (bump_left || bump_right) begin
                        // Bumped on left -> walk right; bumped on right -> walk left
                        // If both bumped, still switch directions (spec: "still switch directions")
                        // Logic: if bump_left, go right; if bump_right, go left
                        if (bump_left) begin
                            next_state = WALKING_RIGHT;
                            dir_reg <= WALKING_RIGHT; // update direction
                        end else if (bump_right) begin
                            next_state = WALKING_LEFT;
                            dir_reg <= WALKING_LEFT; // update direction
                        end
                        // If both bumped, the else-if chain handles: bump_left takes precedence
                        // to ensure a switch occurs (arbitrary but consistent choice).
                    end
                end
            end

            WALKING_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                    // dir_reg keeps its value (remembers right direction)
                end else if (dig) begin
                    next_state = DIGGING;
                end else begin
                    if (bump_left || bump_right) begin
                        // bump_left -> walk left; bump_right -> walk right
                        // if both, still switch directions
                        if (bump_right) begin
                            next_state = WALKING_RIGHT;
                            dir_reg <= WALKING_RIGHT;
                        end else if (bump_left) begin
                            next_state = WALKING_LEFT;
                            dir_reg <= WALKING_LEFT;
                        end
                    end
                end
            end

            FALLING: begin
                // While falling, ignore bumps and dig.
                // When ground reappears (ground=1), resume walking in same direction.
                if (ground) begin
                    // Resume walking in the direction stored in dir_reg
                    // dir_reg holds the last walking direction (0=left, 1=right)
                    if (dir_reg == 2'b00) begin
                        next_state = WALKING_LEFT;
                    end else begin
                        next_state = WALKING_RIGHT;
                    end
                    // dir_reg already holds the correct direction from before the fall
                end else begin
                    // Stay falling, ignore bumps/dig
                end
            end

            DIGGING: begin
                if (!ground) begin
                    // Reach other side (ground=0), fall
                    next_state = FALLING;
                    // dir_reg keeps its value (remembers direction before digging)
                end else begin
                    // Still on ground, keep digging if dig=1
                    if (dig) begin
                        next_state = DIGGING;
                        // dir_reg keeps its value (direction preserved during dig)
                    end else begin
                        // dig=0: stop digging and resume walking in original direction
                        // Since we have dir_reg, we can resume walking
                        if (dir_reg == 2'b00) begin
                            next_state = WALKING_LEFT;
                        end else begin
                            next_state = WALKING_RIGHT;
                        end
                    end
                end
            end
        endcase
    end

    // Output logic (Moore machine: outputs depend only on state)
    assign walk_left = (state == WALKING_LEFT);
    assign walk_right = (state == WALKING_RIGHT);
    assign aaah = (state == FALLING);
    assign digging = (state == DIGGING);

endmodule

