module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    // Internal register holding the current generation
    logic [255:0] state;

    // ---------- Next-state logic (combinational) ----------
    // We compute the next state for every cell in parallel.
    // The grid is 16x16, wrapped toroidally.
    // Row-major ordering: q[15:0] = row 0, q[31:16] = row 1, …, q[255:240] = row 15.

    logic [255:0] next;

    // Declare loop variables as logic to avoid 'int' context issues
    logic [3:0] r, c;
    logic [3:0] r_minus_1, r_plus_1, c_minus_1, c_plus_1;
    logic [3:0] nb; // Neighbour count (max 8, so 4 bits is sufficient)

    always_comb begin
        // Iterate over every cell (r = row 0..15, c = column 0..15)
        for (r = 0; r < 16; r = r + 1) begin
            for (c = 0; c < 16; c = c + 1) begin
                // Linear index into the 256-bit vector
                int idx = (r * 16) + c;

                // Count live neighbours with toroidal wrap‑around.
                // Neighbour positions are (r-1..r+1, c-1..c+1) excluding (r,c).
                nb = 0;

                // Helper values for wrapped row and column
                r_minus_1 = (r - 1 + 16) % 16;
                r_plus_1  = (r + 1) % 16;
                c_minus_1 = (c - 1 + 16) % 16;
                c_plus_1  = (c + 1) % 16;

                // (r-1, c-1)
                nb = nb + state[(r_minus_1 * 16) + c_minus_1];
                // (r-1, c)
                nb = nb + state[(r_minus_1 * 16) + c];
                // (r-1, c+1)
                nb = nb + state[(r_minus_1 * 16) + c_plus_1];
                // (r, c-1)
                nb = nb + state[(r * 16) + c_minus_1];
                // (r, c+1)
                nb = nb + state[(r * 16) + c_plus_1];
                // (r+1, c-1)
                nb = nb + state[(r_plus_1 * 16) + c_minus_1];
                // (r+1, c)
                nb = nb + state[(r_plus_1 * 16) + c];
                // (r+1, c+1)
                nb = nb + state[(r_plus_1 * 16) + c_plus_1];

                // Apply Game of Life rules
                // (1) 0‑1 neighbour  -> 0
                // (2) 2 neighbours    -> keep current state
                // (3) 3 neighbours    -> 1
                // (4) 4+ neighbours   -> 0
                if (nb == 3)
                    next[idx] = 1'b1;
                else if (nb == 2)
                    next[idx] = state[idx];
                else
                    next[idx] = 1'b0;
            end
        end
    end

    // ---------- Sequential logic (positive edge triggered) ----------
    always_ff @(posedge clk) begin
        if (load)
            state <= data;   // synchronous load of initial state
        else
            state <= next;   // advance one generation
    end

    // Output assignment – q follows the internal state
    assign q = state;

endmodule
